import React from 'react';
import '../../App.css';
import Card from '../Card';
import Footer from '../Footer';

function Buy() {
    return (
        <>  
            <div className='buy'>
                <h1>Give us money!!!!!!</h1>
                <h2 className='buy'>Or did you want to check the data?</h2>
            </div>          

            <Card />
            <Footer />
        </>
    );
}

export default Buy;
